namespace Logic.Contracts;

/// <summary>
/// Defines a strategy for resolving collisions when generating short URLs.
/// Different strategies can be used based on the requirements (distributed systems, performance, etc.).
/// </summary>
public interface ICollisionResolutionStrategy
{
    /// <summary>
    /// Generates a unique short URL for collision resolution.
    /// </summary>
    /// <param name="baseShortUrl">The base short URL generated by the primary shortener.</param>
    /// <param name="attempt">The current attempt number (0-based).</param>
    /// <param name="longUrl">The original long URL being shortened.</param>
    /// <returns>A unique short URL that should avoid collisions.</returns>
    string GenerateUniqueShortUrl(string baseShortUrl, int attempt, string longUrl);
}
